226	// ---------- protocol ----------
227	function wireReport(frame) {
228	  const kind = frame.kind;
229	  const score = Number.isFinite(frame.score) ? Math.round(frame.score) : undefined;
230	  if (kind === 'progress') return { kind: 'progress', data: { ...frame } };
231	  if (kind === 'event') return { kind: 'event', event: String(frame.event || frame.tag || 'event'), data: { ...frame } };
232	  if (kind === 'gameOver') {
233	    const prog = frame.progress && typeof frame.progress === 'object' ? frame.progress : { value: frame.progress };
234	    return { kind: 'gameOver', score, progress: prog, data: { ...frame } };
235	  }
236	  if (kind === 'complete') return { kind: 'complete', score };
237	  return frame;
238	}
239	function report(kind, payload = {}) {
240	  const frame = { kind, ...payload };
241	  if (Number.isFinite(frame.score)) frame.score = Math.round(frame.score);
242	  reports.push(frame);
