 const out={raw, sec, capped: raw>cap, mat:0, ess:0, gold:0, gatherMat:0,distillEss:0,synthGold:0,packGold:0, startMat, startEss};
 ...
 out.mat = mat-startMat; out.ess=ess-startEss; out.gold=gold;
 return out;
}
