    for (const r of RECIPES) {
      if (mode !== 'play') break;
      if (r.allRecipes && discovered.size < RECIPES.length - 1) continue;
      let guard = 0;
      while (mode === 'play' && guard++ < 20 && canCraft(r.id).ok && n < 80) {
