  return `${selectedRecipe}|${discovered.size}|${levels.join(',')}|${prestige}|${r.inputs.map(([id]) => Math.round((items[id] || 0) * 10) / 10).join(',')}|${Math.round((items[r.id] || 0) * 10) / 10}|${mode === 'play'}`;
}
