  if (!avail) stateText = `未解锁 · 需先炼成 ${missing.join('、')}`;
  else if (r.allRecipes && discovered.size < RECIPES.length - 1) stateText = `终局配方 · 还需录满其余 ${RECIPES.length - 1 - discovered.size} 张`;
