      if (mode === 'play' && !paused && !noAuto) update(dt);
      renderer.draw(makeView());
    }
    updateUI(true);
  },
  upd: (n = 30, dt = DT) => {
    for (let i = 0; i < n; i++) {
      handleKeys();
