    updateUI(true);
  },
  press: (...codes) => codes.forEach(c => pressed.add(c)),
  clearKeys: () => pressed.clear(),
  setNoAuto: (v) => { noAuto = !!v; },
  setReportTarget: (fn) => { reportTarget = typeof fn === 'function' ? fn : null; },
  state: () => ({
