export const ITEMS = { ...BASE_ITEMS };
for (const r of RECIPES) {
  ITEMS[r.id] = {
    id: r.id, name: r.name, glyph: r.name[0], shape: r.shape, color: r.color,
    tier: r.tier, desc: r.desc, recipe: r,
  };
}

