import { createRequire } from 'module';
const require = createRequire('/tmp/pw/node_modules/');
const { chromium } = require('playwright');
const b = await chromium.launch({ headless:true, executablePath:'/usr/local/bin/chromium', args:['--no-sandbox','--use-gl=swiftshader'] });
const p = await b.newPage({ viewport:{width:1280,height:720} });
const errs=[]; p.on('console',m=>{if(m.type()==='error')errs.push(m.text())}); p.on('pageerror',e=>errs.push(String(e)));
await p.goto('http://localhost:8628/crucible-atelier/', {waitUntil:'load'});
await p.waitForTimeout(500);
await p.click('#startbtn'); await p.waitForTimeout(250);
await p.evaluate(\`(() => { const G=window.G; G.setNoAuto(true); G.grantItem('water',40); G.grantItem('ash',40); G.selectRecipe('mist'); G.overload(); G.overload(); G.overload(); G.overload(); })()\`);
await p.waitForTimeout(500);
await p.screenshot({path:'/mnt/tos/workspace/.scratch/guizang3/crucible-atelier/end-fail.png'});
await p.evaluate(\`(() => { const G=window.G; G.startGame(true); G.setPrestige(2); G.forceComplete(); })()\`);
await p.waitForTimeout(500);
await p.screenshot({path:'/mnt/tos/workspace/.scratch/guizang3/crucible-atelier/end-complete.png'});
console.log('errs', errs);
await b.close();
"

